--- /dev/null
+++ automation/steps/ideamade-workflow.steps.ts
@@ -0,0 +1,84 @@
+import { expect } from "@playwright/test";
+import { Given, Then, When } from "@cucumber/cucumber";
+
+type WorldWithPage = {
+  page: import("@playwright/test").Page;
+  baseUrl?: string;
+};
+
+const byTestId = (id: string) => `[data-testid="${id}"]`;
+
+Given("the user opens the IdeaMade app", async function (this: WorldWithPage) {
+  await this.page.goto(this.baseUrl ?? "/");
+});
+
+Then("the idea empty state is visible", async function (this: WorldWithPage) {
+  await expect(this.page.locator(byTestId("idea-empty-state"))).toBeVisible();
+});
+
+When("the user creates a new idea note", async function (this: WorldWithPage) {
+  await this.page.locator(byTestId("new-idea-button")).click();
+});
+
+When(
+  "the user fills in the idea title with value {string}",
+  async function (this: WorldWithPage, value: string) {
+    await this.page.locator(byTestId("idea-title-input")).fill(value);
+  },
+);
+
+When(
+  "the user fills in the idea body with value {string}",
+  async function (this: WorldWithPage, value: string) {
+    await this.page.locator(byTestId("idea-body-input")).fill(value);
+  },
+);
+
+Then(
+  "the idea list should contain the text {string}",
+  async function (this: WorldWithPage, value: string) {
+    await expect(this.page.locator(byTestId("idea-list"))).toContainText(value);
+  },
+);
+
+Then(
+  "the idea list should not contain the text {string}",
+  async function (this: WorldWithPage, value: string) {
+    await expect(this.page.locator(byTestId("idea-list"))).not.toContainText(value);
+  },
+);
+
+When("the user reloads the page", async function (this: WorldWithPage) {
+  await this.page.reload();
+});
+
+Then(
+  "the idea note {string} is restored with the body text {string}",
+  async function (this: WorldWithPage, title: string, body: string) {
+    await expect(this.page.locator(byTestId("idea-title-input"))).toHaveValue(title);
+    await expect(this.page.locator(byTestId("idea-body-input"))).toHaveValue(body);
+  },
+);
+
+When(
+  "the user selects the idea note {string}",
+  async function (this: WorldWithPage, title: string) {
+    await this.page.getByRole("button", { name: title }).click();
+  },
+);
+
+Then(
+  "the idea note {string} is active",
+  async function (this: WorldWithPage, title: string) {
+    await expect(this.page.locator(byTestId("active-idea-title"))).toContainText(title);
+  },
+);
+
+When(
+  "the user deletes the idea note {string}",
+  async function (this: WorldWithPage, title: string) {
+    await this.page.getByRole("button", { name: title }).click();
+    await this.page.locator(byTestId("delete-idea-button")).click();
+    await this.page.locator(byTestId("confirm-delete-idea-button")).click();
+  },
+);
